from __future__ import annotations

from collections import Counter, defaultdict
from datetime import datetime, timezone
import importlib.metadata
import json
import math
import platform
from pathlib import Path
import statistics
import subprocess
import sys

from .gemini import generation_config
from .io import read_jsonl, write_json, write_jsonl
from .scoring import normalize_answer


LENS_MODES = ("lens_compact", "lens_balanced", "lens_detailed")


def _mean(values: list[float]) -> float | None:
    return statistics.fmean(values) if values else None


def _median(values: list[float]) -> float | None:
    return statistics.median(values) if values else None


def _percentile(values: list[float], percentile: float) -> float | None:
    if not values:
        return None
    ordered = sorted(values)
    index = (len(ordered) - 1) * percentile
    lower = math.floor(index)
    upper = math.ceil(index)
    if lower == upper:
        return ordered[lower]
    return ordered[lower] + (ordered[upper] - ordered[lower]) * (index - lower)


def _metric(rows: list[dict]) -> dict:
    successful = [row for row in rows if row["status"] == "ok"]
    correct = sum(row["correct"] is True for row in successful)
    return {
        "requested": len(rows),
        "successful": len(successful),
        "failed": len(rows) - len(successful),
        "correct": correct,
        "accuracy": correct / len(successful) if successful else None,
        "failure_rate": (len(rows) - len(successful)) / len(rows) if rows else None,
    }


def _group(rows: list[dict], keys: tuple[str, ...]) -> list[dict]:
    groups: dict[tuple, list[dict]] = defaultdict(list)
    for row in rows:
        groups[tuple(row[key] for key in keys)].append(row)
    output = []
    for values, members in sorted(groups.items()):
        output.append({**dict(zip(keys, values)), **_metric(members)})
    return output


def _metric_index(rows: list[dict]) -> dict[tuple[str, str], dict]:
    return {(row["model_id"], row["mode"]): row for row in rows}


def _paired(rows: list[dict]) -> list[dict]:
    by_key = {
        (row["model_id"], row["question_id"], row["mode"]): row
        for row in rows
    }
    output = []
    model_ids = sorted({row["model_id"] for row in rows})
    question_ids = sorted({row["question_id"] for row in rows})
    for model_id in model_ids:
        for mode in LENS_MODES:
            counts = Counter()
            for question_id in question_ids:
                native = by_key.get((model_id, question_id, "native_vision"))
                lens = by_key.get((model_id, question_id, mode))
                if native is None or lens is None:
                    continue
                if native["status"] != "ok" or lens["status"] != "ok":
                    counts["excluded_failure"] += 1
                    continue
                native_correct = bool(native["correct"])
                lens_correct = bool(lens["correct"])
                counts[
                    f"native_{'correct' if native_correct else 'wrong'}_lens_"
                    f"{'correct' if lens_correct else 'wrong'}"
                ] += 1
            retained = counts["native_correct_lens_correct"]
            lost = counts["native_correct_lens_wrong"]
            output.append(
                {
                    "model_id": model_id,
                    "lens_mode": mode,
                    "paired_successful": sum(counts.values()) - counts["excluded_failure"],
                    "native_correct_lens_correct": retained,
                    "native_correct_lens_wrong": lost,
                    "native_wrong_lens_correct": counts["native_wrong_lens_correct"],
                    "native_wrong_lens_wrong": counts["native_wrong_lens_wrong"],
                    "excluded_failure": counts["excluded_failure"],
                    "native_correct_retention": retained / (retained + lost)
                    if retained + lost
                    else None,
                }
            )
    return output


def _quality(rows: list[dict]) -> list[dict]:
    index = _metric_index(_group(rows, ("model_id", "mode")))
    output = []
    for model_id in sorted({row["model_id"] for row in rows}):
        native = index[(model_id, "native_vision")]["accuracy"]
        no_visual = index[(model_id, "no_visual")]["accuracy"]
        for mode in LENS_MODES:
            accuracy = index[(model_id, mode)]["accuracy"]
            output.append(
                {
                    "model_id": model_id,
                    "mode": mode,
                    "native_accuracy": native,
                    "lens_accuracy": accuracy,
                    "no_visual_accuracy": no_visual,
                    "absolute_drop_percentage_points": (native - accuracy) * 100
                    if native is not None and accuracy is not None
                    else None,
                    "native_quality_retention": accuracy / native
                    if native and accuracy is not None
                    else None,
                    "uplift_over_no_visual_percentage_points": (accuracy - no_visual) * 100
                    if accuracy is not None and no_visual is not None
                    else None,
                }
            )
    return output


def _latency(rows: list[dict], memory: dict) -> dict:
    groups: dict[tuple[str, str], list[dict]] = defaultdict(list)
    for row in rows:
        groups[(row["model_id"], row["mode"])].append(row)
    api = []
    for (model_id, mode), members in sorted(groups.items()):
        values = [float(row["latency_ms"]) for row in members if row["status"] == "ok"]
        api.append(
            {
                "model_id": model_id,
                "mode": mode,
                "count": len(values),
                "mean_ms": _mean(values),
                "median_ms": _median(values),
                "p95_ms": _percentile(values, 0.95),
            }
        )
    return {
        "api": api,
        "lens_preprocessing": {
            "records": memory.get("description_records"),
            "mean_ms": memory.get("lens_processing_mean_ms"),
            "median_ms": memory.get("lens_processing_median_ms"),
        },
    }


def _usage(rows: list[dict], descriptions: list[dict]) -> dict:
    groups: dict[tuple[str, str], list[dict]] = defaultdict(list)
    for row in rows:
        groups[(row["model_id"], row["mode"])].append(row)
    api = []
    fields = (
        "promptTokenCount",
        "candidatesTokenCount",
        "thoughtsTokenCount",
        "totalTokenCount",
    )
    for (model_id, mode), members in sorted(groups.items()):
        totals = {field: sum(int(row.get("usage", {}).get(field, 0)) for row in members) for field in fields}
        api.append(
            {
                "model_id": model_id,
                "mode": mode,
                "successful_requests": sum(row["status"] == "ok" for row in members),
                "totals": totals,
                "mean_per_request": {
                    field: totals[field] / len(members) if members else None for field in fields
                },
            }
        )
    lens = {}
    for detail in ("compact", "balanced", "detailed"):
        values = [row["token_counts"][detail] for row in descriptions]
        lens[detail] = {
            "records": len(values),
            "total_qwen3_4b_tokens": sum(values),
            "mean_qwen3_4b_tokens": _mean(values),
            "median_qwen3_4b_tokens": _median(values),
        }
    return {
        "api_usage": api,
        "lens_description_tokens": lens,
        "cost": None,
        "cost_note": "No cost is reported because account billing tier and charged rates were not independently measured.",
    }


def _failure_rows(rows: list[dict]) -> list[dict]:
    output = []
    for row in rows:
        if row["mode"] not in LENS_MODES or row["correct"] is True:
            continue
        if row["status"] != "ok":
            classification = "E_MODEL_OR_API_FAILURE"
            basis = "request status was not ok"
        else:
            category = row["category"]
            evidence = normalize_answer(row["lens_text"] or "", category)
            accepted = [normalize_answer(item, category) for item in row["accepted_answers"]]
            has_answer = any(answer and answer in evidence for answer in accepted)
            classification = (
                "C_MODEL_FAILED_WITH_ANSWER_STRING_PRESENT"
                if has_answer
                else "A_INFORMATION_MISSING_OR_NOT_STRING_MATCHED"
            )
            basis = "conservative normalized answer-string presence heuristic"
        output.append(
            {
                "model_id": row["model_id"],
                "image_id": row["image_id"],
                "question_id": row["question_id"],
                "category": row["category"],
                "mode": row["mode"],
                "question": row["question"],
                "ground_truth": row["ground_truth"],
                "parsed_answer": row["parsed_answer"],
                "status": row["status"],
                "classification": classification,
                "classification_basis": basis,
            }
        )
    return output


def _repeatability(rows: list[dict], repeats: list[dict]) -> dict:
    baseline = [
        row
        for row in rows
        if row["image_id"] in {item["image_id"] for item in repeats}
    ]
    groups: dict[tuple[str, str, str], list[dict]] = defaultdict(list)
    for row in baseline + repeats:
        groups[(row["model_id"], row["question_id"], row["mode"])].append(row)
    by_model_mode: dict[tuple[str, str], list[bool]] = defaultdict(list)
    excluded = 0
    for (model_id, _, mode), members in groups.items():
        members.sort(key=lambda row: row["repeat_index"])
        if len(members) != 3 or any(row["status"] != "ok" for row in members):
            excluded += 1
            continue
        answers = [row["normalized_answer"] for row in members]
        by_model_mode[(model_id, mode)].append(len(set(answers)) == 1)
    details = []
    for (model_id, mode), values in sorted(by_model_mode.items()):
        details.append(
            {
                "model_id": model_id,
                "mode": mode,
                "groups": len(values),
                "exact_stable_groups": sum(values),
                "exact_stability_rate": sum(values) / len(values) if values else None,
            }
        )
    return {
        "status": "complete"
        if len(repeats) == 2 * 52 * len({row["model_id"] for row in rows}) * 5
        and len(baseline) == 52 * len({row["model_id"] for row in rows}) * 5
        else "incomplete",
        "definition": "all three normalized answers are identical",
        "repeats_per_group": 3,
        "primary_baseline_requests": len(baseline),
        "repeat_requests": len(repeats),
        "expected_repeat_requests": 2 * 52 * len({row["model_id"] for row in rows}) * 5,
        "measured_groups": sum(len(values) for values in by_model_mode.values()),
        "excluded_groups": excluded,
        "by_model_mode": details,
    }


def _environment(model_ids: list[str]) -> dict:
    packages = {}
    for name in ("torch", "ultralytics", "easyocr", "transformers", "psutil", "Pillow"):
        try:
            packages[name] = importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:
            packages[name] = None
    gpu = None
    try:
        process = subprocess.run(
            ["nvidia-smi", "--query-gpu=name,driver_version,memory.total", "--format=csv,noheader"],
            check=False,
            capture_output=True,
            text=True,
            timeout=15,
        )
        if process.returncode == 0:
            gpu = process.stdout.strip() or None
    except (OSError, subprocess.TimeoutExpired):
        gpu = None
    return {
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "python": sys.version,
        "platform": platform.platform(),
        "processor": platform.processor(),
        "gpu_query": gpu,
        "packages": packages,
        "models": [
            {"model_id": model_id, "generation_config": generation_config(model_id)}
            for model_id in model_ids
        ],
        "api": "Gemini generateContent v1beta",
    }


def analyze(artifact_root: Path) -> dict:
    rows = read_jsonl(artifact_root / "parsed-model-results.jsonl")
    repeats_path = artifact_root / "repeatability-results.jsonl"
    repeats = read_jsonl(repeats_path) if repeats_path.is_file() else []
    descriptions = read_jsonl(artifact_root / "lens-descriptions.jsonl")
    memory = json.loads((artifact_root / "memory-summary.json").read_text(encoding="utf-8"))
    overall_rows = _group(rows, ("model_id", "mode"))
    category_rows = _group(rows, ("model_id", "mode", "category"))
    paired = _paired(rows)
    quality = _quality(rows)
    failures = _failure_rows(rows)
    model_ids = sorted({row["model_id"] for row in rows})
    repeatability = _repeatability(rows, repeats)
    overall = {
        "benchmark_version": rows[0]["benchmark_version"] if rows else None,
        "requests": len(rows),
        "images": len({row["image_id"] for row in rows}),
        "questions": len({row["question_id"] for row in rows}),
        "models": model_ids,
        "modes": sorted({row["mode"] for row in rows}),
        "successful": sum(row["status"] == "ok" for row in rows),
        "failed": sum(row["status"] != "ok" for row in rows),
        "retries": sum(row["retries"] for row in rows),
        "denominator_policy": "API and parse failures are excluded from accuracy and counted separately.",
        "results": overall_rows,
        "repeatability": repeatability,
    }
    category = {
        "results": category_rows,
        "balanced_native_gap_percentage_points": [
            {
                "model_id": model_id,
                "category": category_name,
                "gap": (
                    native["accuracy"] - balanced["accuracy"]
                )
                * 100,
            }
            for model_id in model_ids
            for category_name in sorted({row["category"] for row in rows})
            for native in [
                next(
                    item
                    for item in category_rows
                    if item["model_id"] == model_id
                    and item["mode"] == "native_vision"
                    and item["category"] == category_name
                )
            ]
            for balanced in [
                next(
                    item
                    for item in category_rows
                    if item["model_id"] == model_id
                    and item["mode"] == "lens_balanced"
                    and item["category"] == category_name
                )
            ]
            if native["accuracy"] is not None and balanced["accuracy"] is not None
        ],
    }
    matrix = {
        model_id: {
            mode: next(
                row
                for row in overall_rows
                if row["model_id"] == model_id and row["mode"] == mode
            )
            for mode in sorted({row["mode"] for row in rows})
        }
        for model_id in model_ids
    }
    failure_counts = Counter(row["classification"] for row in failures)
    failure_by_model = Counter((row["model_id"], row["classification"]) for row in failures)
    failure_by_mode = Counter((row["mode"], row["classification"]) for row in failures)
    failure_by_category = Counter((row["category"], row["classification"]) for row in failures)
    token_means = {
        detail: _mean([row["token_counts"][detail] for row in descriptions])
        for detail in ("compact", "balanced", "detailed")
    }
    token_quality = [
        {
            **row,
            "mean_qwen3_4b_description_tokens": token_means[row["mode"].removeprefix("lens_")],
        }
        for row in quality
    ]
    write_json(artifact_root / "overall-results.json", overall)
    write_json(artifact_root / "category-results.json", category)
    write_json(artifact_root / "model-mode-matrix.json", matrix)
    write_json(artifact_root / "paired-results.json", paired)
    write_json(artifact_root / "quality-retention.json", quality)
    write_json(artifact_root / "token-quality-tradeoff.json", token_quality)
    write_json(artifact_root / "latency-summary.json", _latency(rows, memory))
    write_json(artifact_root / "usage-summary.json", _usage(rows, descriptions))
    write_jsonl(artifact_root / "failure-analysis.jsonl", failures)
    write_json(
        artifact_root / "failure-analysis-summary.json",
        {
            "counts": dict(failure_counts),
            "by_model": [
                {"model_id": key[0], "classification": key[1], "count": count}
                for key, count in sorted(failure_by_model.items())
            ],
            "by_mode": [
                {"mode": key[0], "classification": key[1], "count": count}
                for key, count in sorted(failure_by_mode.items())
            ],
            "by_category": [
                {"category": key[0], "classification": key[1], "count": count}
                for key, count in sorted(failure_by_category.items())
            ],
            "rows": len(failures),
            "manual_only_classes": [
                "B_LENS_INFORMATION_INCORRECT",
                "D_QUESTION_OR_REFERENCE_AMBIGUOUS",
            ],
            "limitation": "A/C are conservative string-presence heuristics; semantic sufficiency and incorrect Lens facts require manual adjudication.",
        },
    )
    write_json(artifact_root / "repeatability-summary.json", repeatability)
    write_json(artifact_root / "environment.json", _environment(model_ids))
    return overall
